package com.aos.statusbar;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;
public class MainActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,40,32,32);TextView t=new TextView(this);t.setText("AOS • Custom Status Bar");t.setTextSize(24);l.addView(t);Button a=new Button(this);a.setText("1 • Grant overlay permission");a.setOnClickListener(v->{if(!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));});l.addView(a);Button n=new Button(this);n.setText("2 • Enable notification access");n.setOnClickListener(v->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS")));l.addView(n);Button s=new Button(this);s.setText("3 • Start AOS status bar");s.setOnClickListener(v->{if(Settings.canDrawOverlays(this)){if(Build.VERSION.SDK_INT>=26)startForegroundService(new Intent(this,OverlayService.class));else startService(new Intent(this,OverlayService.class));}else Toast.makeText(this,"Grant overlay permission first",0).show();});l.addView(s);setContentView(l);}}